'use strict';
// Additive current supplement; frozen source and scientific views stay intact.
(()=>{
 const retained=window.HarvestView;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const num=v=>v==null?'Not recorded':Number(v).toLocaleString('en-US',{maximumFractionDigits:2});
 const date=v=>{if(!v)return 'Not recorded';const d=new Date(v);return Number.isNaN(+d)?esc(v):d.toISOString().replace('T',' ').replace(/\.\d+Z$/,' UTC')};
 const sourceLink=(href,label)=>/^https?:\/\//.test(href||'')?`<a href="${esc(href)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`:esc(label);
 const fileLink=(files,name,label)=>files.some(f=>f.path===name)?`<a href="${esc(name)}" download>${esc(label)} ↓</a>`:'Metadata not published in this build';
 function selectionFigure(m){
  const n=m.indexed;
  const step=(title,items)=>`<div class="selection-step"><p>${title}</p><div class="selection-track" aria-hidden="true">${items.map(i=>`<span class="${i.color}" style="width:${i.value/n*100}%"></span>`).join('')}</div><ul class="selection-key">${items.map(i=>`<li><i class="${i.color}" aria-hidden="true"></i>${esc(i.label)} ${num(i.value)}</li>`).join('')}</ul></div>`;
  return `<figure class="selection-figure" id="current-selection-figure"><figcaption>Inherited metadata → planned YouTube selection</figcaption>${step(`<strong>${num(n)} indexed IDs → ${num(m.eligible)} eligible</strong>`,[{label:'Eligible',value:m.eligible,color:'screen-eligible'},{label:'Under 300 seconds',value:m.short,color:'held-short'},{label:'Unknown duration',value:m.unknown,color:'held-unknown'},{label:'Conflicting duration',value:m.conflict,color:'held-conflict'}])}${step(`<strong>${num(m.eligible)} eligible = ${num(m.basharEligible)} Bashar-labeled + ${num(m.otherEligible)} other</strong>`,[{label:'Bashar-labeled eligible',value:m.basharEligible,color:'source-bashar'},{label:'Other eligible',value:m.otherEligible,color:'source-other'},{label:'Screened out / held',value:n-m.eligible,color:'held-screen'}])}${step(`<strong>${num(m.selected)} planned = ${num(m.basharSelected)} Bashar + ${num(m.otherSelected)} other; ${num(m.capHeld)} Bashar cap-held</strong>`,[{label:'Bashar selected',value:m.basharSelected,color:'source-bashar'},{label:'Other selected',value:m.otherSelected,color:'source-other'},{label:'Bashar cap-held',value:m.capHeld,color:'held-cap'},{label:'Screened out / held',value:n-m.eligible,color:'held-screen'}])}<p class="caption">Every bar uses the same ${num(n)}-ID scale. This is an inherited-metadata screening and planning figure, not a completed crawl. The one historical Shorts flag overlaps the under-300-second group and is not added again. Actual YouTube downloads: 0.</p></figure>`;
 }
 function bravePanel(s,files){
  const b=s.braveWatch,c=s.braveControl,r=s.braveRuntime;
  if(!b)return '';
  return `<section id="current-brave"><h3>Official Brave: the tunnel still returns 403</h3><p>One ordinary watch navigation, recorded ${date(b.checkedAt)}: ${sourceLink(b.requestedUrl,'Original watch URL')}. ${esc(b.navigationError||b.outcome)}.</p><p>Brave’s target-bound network log records ${num(b.targetConnectRequestsObserved)} CONNECT to <code>www.youtube.com:443</code>, HTTP ${num(b.proxyConnectStatus)} from ${esc(b.proxyTunnelEvidence?.find(x=>x.server)?.server||'server not recorded')}. No origin page response, video, audio or caption was obtained. The 403’s underlying cause remains unknown.</p><p class="caption">${esc(r?.browserVersion)} · ${esc(b.engine?.product)}. Official package checksum verified. The allowed Pages control ${c?.passed?'passed with HTTP 200 and TLS verification':'has no verified success in this snapshot'}; the inherited proxy and certificate verification stayed enabled. This is one diagnostic, not 942 item attempts.</p><details><summary>Inspect the official Brave package</summary><p>${sourceLink(r?.sourceUrl,'Official release asset')} · ${num(r?.bytes)} bytes.</p><p class="hash">Package SHA-256 ${esc(r?.sha256)}</p></details><p>${fileLink(files,'youtube-access-brave-watch.json','Exact Brave source outcome')} · ${fileLink(files,'youtube-access-brave-control.json','Verified HTTPS control')} · ${fileLink(files,'youtube-access-brave-runtime.json','Official package and dependency receipt')}</p></section>`;
 }
 function current(s,data,files){
  const sources=s.sources||{};
  return `<section class="section panel" id="harvest-current-supplement"><div class="section-heading"><h2>Current collection policy and execution</h2><p>Selections describe the bounded collection plan. They do not establish downloads, complete channel coverage or authorized cloud storage. ${fileLink(files,'youtube-access-report.md','Read the current supplement report')}</p></div>${policyPanel(sources,files)}${runnerPanel(sources,files)}<div class="two-columns">${bravePanel(sources,files)}${drivePanel(sources,files)}</div>${audioPanel(data)}${downloadPanel(files)}</section>`;
 }
 // Bound after the source owners' final export; no inferred readiness defaults.
 function policyPanel(s,files){
  const p=s.policy,c=s.policyDefinition;if(!p)return '';
  const a=p.all_upload_ids,b=p.explicit_bashar_association,o=p.other_not_bashar_labeled,d=p.default,alt=p.conservative_all_materials_alternative;
  const m={indexed:a.indexed,eligible:a.eligible,short:a.under_minimum,unknown:a.unknown_duration,conflict:a.conflicting_duration,basharEligible:b.eligible,otherEligible:o.eligible,selected:d.total_new_youtube_ids_selected,basharSelected:d.new_bashar_selected,otherSelected:d.other_selected,capHeld:d.eligible_bashar_held_by_cap};
  return `<section id="current-policy"><h3>${num(d.total_new_youtube_ids_selected)} YouTube IDs selected; downloads remain zero</h3><p>The default plan selects ${num(d.new_bashar_selected)} Bashar-associated YouTube upload IDs across all indexed publishers and repost routes, plus ${num(d.other_selected)} other eligible IDs. The ${num(d.independent_retained_podcasts_separate_source_type)} retained publisher podcasts are a separate source type and do not consume the YouTube-video cap.</p><p>Exclude Shorts and videos shorter than ${num(c?.minimum_duration_seconds)} seconds. Unknown or conflicting duration metadata is held for verification. Selections use inherited metadata and still require fresh source checks before collection.</p><p class="caption">Inventory capture: ${date(p.inventory_capture_time)}. Association labels come from retained metadata, not verified speaker identity.</p>${selectionFigure(m)}
  <details id="current-policy-scope"><summary>Inspect the cap scenario and indexed channel scope</summary><div class="table-wrap"><table><thead><tr><th>Scenario</th><th>Bashar YouTube IDs</th><th>Other YouTube IDs</th><th>Total planned</th><th>Separate podcast reservation</th></tr></thead><tbody><tr><th scope="row">Default: YouTube-video cap</th><td>${num(d.new_bashar_selected)}</td><td>${num(d.other_selected)}</td><td>${num(d.total_new_youtube_ids_selected)}</td><td>None deducted</td></tr><tr><th scope="row">Optional: conservative all-material cap</th><td>${num(alt.new_bashar_selected)}</td><td>${num(alt.other_selected)}</td><td>${num(alt.total_new_youtube_ids_selected)}</td><td>${num(alt.reserved_existing_bashar_podcast_materials)} existing RSS recordings</td></tr></tbody></table></div><p>${num(b.indexed)} explicitly Bashar-associated indexed upload IDs; ${num(p.bashar_relevant_literal_routes)} relevant literal account routes (${num(p.routes_with_explicit_bashar_indexed_videos)} with indexed Bashar video edges and ${num(p.bashar_branded_routes_with_zero_indexed_videos)} branded routes with none). These are overlapping inherited inventory units, not whole-channel lifetime counts.</p><p>${num(p.bashar_video_route_edges)} explicit video–route edges cover ${num(p.bashar_ids_with_any_route)} distinct Bashar IDs; ${num(p.bashar_ids_without_route)} have no route edge. One upload can appear on several source routes. Full lifetime Bashar uploads and all uploads across every reposting channel: <strong>unknown</strong>.</p><p class="caption">The roughly ${num(p.requested_approximate_video_target)}-video request is a target; this retained inventory contains ${num(a.indexed)} distinct IDs. Original-session identity and reuse across different upload IDs remain unresolved. Selection method: ${esc(c?.sampling?.replaceAll('_',' '))}.</p></details>
  <p>${fileLink(files,'youtube-access-policy-summary.json','Policy counts and scope')} · ${fileLink(files,'youtube-access-selected-default.jsonl','All default selected IDs')} · ${fileLink(files,'youtube-access-selection.csv','Every indexed ID and decision')} · ${fileLink(files,'youtube-access-bashar-routes.csv','Bashar route metadata')}</p></section>`;
 }
 function runnerPanel(s,files){
  const p=s.runnerSummary,d=s.runnerDryRun,b=s.runnerBlocked;if(!p)return '';
  return `<section id="current-runner"><h3>Policy-aware runner: blocked before collection</h3><div class="table-wrap"><table><thead><tr><th>Planned operation</th><th>Jobs</th><th>Execution evidence</th></tr></thead><tbody>${Object.entries(p.by_kind||{}).map(([kind,n])=>`<tr><th scope="row">${esc(kind==='metadata'?'Metadata refresh':kind==='captions'?'Caption retrieval':kind==='video'?'Video retrieval':kind)}</th><td>${num(n)}</td><td>Queued; not attempted</td></tr>`).join('')}</tbody></table></div><p>${num(p.jobs)} planned jobs over ${num(p.items)} indexed items. Worker job attempts: <strong>${num(p.attempts)}</strong>; Bashar video slots used: <strong>${num(p.bashar_unique_youtube_slots_used)}</strong>; verified quarantine artifacts: <strong>${num(p.verified_quarantine_artifacts)}</strong>. Network collection requests in the dry run: ${num(d?.network_collection_requests)}.</p><p>Access gate ready: ${d?.gate?.ready===true?'yes':d?.gate?.ready===false?'no':'not recorded'}. Bounded-controller outcome: <code>${esc(b?.status||'Not recorded')}</code>. A successful ordinary watch probe for the same current runtime is required before any job claim or source request.</p><p class="caption">The ${num(p.by_kind?.video)} planned video jobs and their caption jobs share the same upload-ID cap; they are not twice as many videos. The older worker ledger below preserves its earlier inventory-wide queue. Neither queue is an attempted- or completed-download count.</p><p>${fileLink(files,'youtube-access-runner-summary.json','Exact runner plan and counters')} · ${fileLink(files,'youtube-access-runner-dry-run.json','Offline access-gate state')} · ${fileLink(files,'youtube-access-runner-blocked.json','Blocked controller receipt')} · ${fileLink(files,'youtube-access-runner-workflow.md','Runner workflow')}</p></section>`;
 }
 function drivePanel(s,files){
  const d=s.drive;if(!d)return '';
  return `<section id="current-drive"><h3>Drive workflow prepared; connection pending</h3><p>Recorded ${date(d.checked_at)}. Apps connection choice received: ${d.apps_connection_choice_received?'yes':'no'}. OAuth completion observed: ${d.oauth_completion_observed?'yes':'no'}. A connection choice is not authentication.</p><div class="table-wrap"><table><tbody><tr><th scope="row">Callable Drive tools / configured remotes</th><td>${num(d.callable_drive_tool_count)} / ${num(d.configured_rclone_remotes)}</td></tr><tr><th scope="row">Actual Drive folders / upload attempts / uploaded files</th><td>${num(d.actual_drive_folder_count)} / ${num(d.actual_drive_upload_attempts)} / ${num(d.actual_drive_uploaded_files)}</td></tr><tr><th scope="row">Reported allowance / actual quota check</th><td>${num(d.user_reported_storage_allowance_tb)} TB, user-reported / ${d.actual_quota_checked?'checked':'not verified'}</td></tr></tbody></table></div><p>Local archive plan: ${num(d.plan?.canonical_file_count)} canonical source files (${num(d.plan?.canonical_bytes)} bytes), plus ${num(d.plan?.local_metadata_sidecar_and_manifest_files)} local metadata sidecars/manifests: ${num(d.plan?.planned_total_upload_files)} planned uploads. This is not an uploaded-file count.</p><p class="caption">${esc(d.blocked_step)} No authenticated account, remote quota or effective sharing permissions are established by the offline workflow tests.</p><p>${fileLink(files,'youtube-access-drive-state.json','Exact storage state')} · ${fileLink(files,'youtube-access-drive-plan.json','Local archive manifest')} · ${fileLink(files,'youtube-access-drive-workflow.md','Connection and archive workflow')}</p></section>`;
 }
 function audioPanel(data){
  const old=data.publisherAudio,extra=data.accessRepair?.athinaPublisher,asr=data.asr,extraAsr=data.accessRepair?.athinaAsr;
  const audio=(old?.records||[]).concat(extra?.records||[]).filter(r=>r.status==='completed');
  const full=(asr?.records||[]).filter(r=>r.status==='completed'&&r.transcribedScope==='full_decoded_audio').length+(extraAsr?.status==='completed'&&extraAsr.transcribedScope==='full_decoded_audio'?1:0);
  return `<p class="caption"><strong>Independent publisher material remains separate:</strong> ${num(audio.length)} saved audio files across the original ${num(old?.completed_audio_files)}-episode cohort and the separate ${num(extra?.completed_audio_files)} Athina episode; ${num(full)} full-audio machine-ASR passes. These are not YouTube video downloads or validated transcript accuracy. Source hashes and dated receipts remain in the preserved sections below.</p>`;
 }
 function downloadPanel(files){
  const chosen=files.filter(f=>f.path.startsWith('youtube-access-'));
  return `<details id="current-supplement-downloads"><summary>Download current policy, runner, Brave and storage metadata</summary><ul class="artifact-list">${chosen.map(f=>`<li><a href="${esc(f.path)}" download>${esc(f.label)} ↓</a><small>${num(f.bytes)} bytes · ${esc(f.kind)}</small><div class="hash">SHA-256 ${esc(f.sha256)}</div></li>`).join('')}</ul><p class="caption">These files contain reviewed metadata and workflow states. No private browser profile, credential file, raw recording or full transcript is published here.</p></details>`;
 }
 window.HarvestView={...retained,render:(data,files)=>{
  const html=retained.render(data,files),s=data?.currentSupplement;
  if(!s)return html;
  const marker='<section class="section panel" id="harvest-access-repair">';
  if(!html.includes(marker))throw Error('Retained acquisition section changed; current supplement insertion requires review');
  return html.replace(marker,current(s,data,files)+marker);
 }};
})();
